def walk(path, out):
    out.append(path)
    for e in repo.list(path):
        p = path + "/" + e if path != "." else e
        if e.endswith("/"):
            walk(p.rstrip("/"), out)
        else:
            out.append(p)

out = []
walk(".", out)
result({"files": out})

